// === Tab: mySketch ===
let mass = [];
let positionX = [];
let positionY = [];
let velocityX = [];
let velocityY = [];
let num = 1000;
let timer = 50
let threshold = 400; //default 320
let friction = 0.99;

/////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	fill(64, 255, 255, 192);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
	background(32);
	if (frameCount % timer == 0) {
		addNewParticle(random(width), random(height));
	}

	for (let particleA = 0; particleA < mass.length; particleA++) {
		let accelerationX = 0;
		let accelerationY = 0;

		for (let particleB = 0; particleB < mass.length; particleB++) {
			if (particleA != particleB) {
				let distanceX = positionX[particleB] - positionX[particleA];
				let distanceY = positionY[particleB] - positionY[particleA];

				let distance = sqrt(distanceX * distanceX + distanceY * distanceY);
				if (distance < 1) distance = 1;

				let force = (distance - threshold) * mass[particleB] / distance;
				accelerationX += force * distanceX;
				accelerationY += force * distanceY;
			}
		}

		velocityX[particleA] = velocityX[particleA] * friction + mass[particleA] * accelerationX;
		velocityY[particleA] = velocityY[particleA] * friction + mass[particleA] * accelerationY;
	}

	for (let particle = 0; particle < mass.length; particle++) {
		positionX[particle] += velocityX[particle];
		positionY[particle] += velocityY[particle];

		ellipse(positionX[particle], positionY[particle], mass[particle] * 1000, mass[particle] * 1000);
	}
	if (mass.length > num) {
		mass.shift();
		positionX.shift();
		positionY.shift();
		velocityX.shift();
		velocityY.shift();
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function addNewParticle(x, y) {
	mass.push(random(0.003, 0.03));
	positionX.push(x);
	positionY.push(y);
	velocityX.push(0);
	velocityY.push(0);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseClicked() {
	addNewParticle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function mouseDragged() {
	addNewParticle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

